const keys = [];
$input.all().forEach(it => { (it.json.keys || []).forEach(k => { if (!k.is_archived) keys.push(k); }); });
const tr = (k, l) => { const t = (k.translations || []).find(x => x.language_iso === l); return t ? t : null; };
const de = { sie: 0, du: 0, sieKeys: [], duKeys: [] };
const pt = { voce: 0, tu: 0, login: 0, entrar: 0, iniciarSessao: 0, sessaoKeys: [], loginKeys: [] };
const reSie = /\b(Sie|Ihr|Ihre|Ihren|Ihrem|Ihrer|Ihnen)\b/;
const reDu = /\b(du|dich|dir|dein|deine|deinen|deinem|deiner|deines)\b/i;
const imperativeDu = /\b(versuche|gib|klicke|lade|wähle|melde)\b/i;
const auth = [];
keys.forEach(k => {
  const name = k.key_name.web || k.key_name.other;
  const d = tr(k, 'de'); const p = tr(k, 'pt');
  const dt = d ? d.translation : ''; const pt_ = p ? p.translation : '';
  if (reSie.test(dt)) { de.sie++; if (de.sieKeys.length < 25) de.sieKeys.push(name + ' | ' + dt.slice(0, 90) + ' | ' + (d.modified_by_email||'')); }
  if (reDu.test(dt) || imperativeDu.test(dt)) { de.du++; if (de.duKeys.length < 25) de.duKeys.push(name + ' | ' + dt.slice(0, 90)); }
  if (/\bvocê\b/i.test(pt_)) pt.voce++;
  if (/\b(tu|teu|tua)\b/i.test(pt_)) pt.tu++;
  if (/\blogin\b/i.test(pt_)) { pt.login++; if (pt.loginKeys.length < 15) pt.loginKeys.push(name + ' | ' + pt_.slice(0, 90)); }
  if (/\bentrar\b/i.test(pt_)) pt.entrar++;
  if (/sess[aã]o/i.test(pt_)) { pt.iniciarSessao++; if (pt.sessaoKeys.length < 15) pt.sessaoKeys.push(name + ' | ' + pt_.slice(0, 90)); }
  if (name.indexOf('auth::') === 0) auth.push({ id: k.key_id, name, en: (tr(k,'en')||{}).translation, de: dt, pt: pt_ });
});
return [{ json: { total: keys.length, de, pt, auth } }];
